function a(t){const n=t instanceof Date?t:new Date(t),e=n.getFullYear(),o=String(n.getMonth()+1).padStart(2,"0"),r=String(n.getDate()).padStart(2,"0");return`${e}-${o}-${r}`}function c(t){const n=t instanceof Date?t:new Date(t),e=String(n.getHours()).padStart(2,"0"),o=String(n.getMinutes()).padStart(2,"0");return`${e}:${o}`}function i(t){const n=t instanceof Date?t:new Date(t);return`${a(n)} ${c(n)}`}export{i as f};
